import { put, call } from 'redux-saga/effects';
import {
    LOGIN_FAILED,
    loginSuccess, receiveSession,
} from '../actions/common'
import UserService from "../services/user";
import subscribeUserToPush from "../../worker/swRegister";




export default function* loginRequested({email, password}) {
    try {
        const backend = yield call(UserService.login, email, password);
        if(backend.token){
            const profile = yield call(UserService.decodeToken, backend.token);
            const reciveCheck = {
                email: email,
                profile: JSON.parse(JSON.stringify(profile)),
                page: 0,
                token: backend.token,
                routes: JSON.parse(JSON.stringify(backend.routes))
            }
            subscribeUserToPush(reciveCheck.token)
            yield put(receiveSession(reciveCheck));
            yield put(loginSuccess());
        } else {
            yield put({type: LOGIN_FAILED})
        }
    } catch (err) {
        yield put({type: LOGIN_FAILED});
    }
}
