import React, {Component} from 'react';
import {includes} from "lodash";

class Sections extends Component {
    constructor(props) {
        super(props);
    }
    render() {
        return (
            <div>
                <div className="row p-0 m-0 mt-2 mb-2 col-12 justify-content-center ">
                    <div className="col-6 mt-1 row justify-content-center ">
                        <button className="btn col-11 btn-sm btn-black border-0 "
                                onClick={() => this.props.pagehandler('1', 'create', {}, '0')}> Nuevo
                        </button>
                    </div>
                    <div className="col-6 mt-1 row justify-content-center ">
                        <button className="btn col-11 btn-sm btn-black border-0"
                                onClick={() => this.props.pagehandler('0', 'read', {}, '0')}>Tabla
                        </button>
                    </div>
                    {
                        this.props.modules === 'cashin' ? <div className="col-6 mt-1 row justify-content-center">
                            <button className="btn col-11 btn-sm btn-black border-0"
                                    onClick={() => this.props.pagehandler('0', 'read', {accepted: false, confirmed: false}, '0')}>Sin
                                Vender
                            </button>
                        </div> : <div/>
                    }
                    {
                        this.props.modules === 'cashin' ? <div className="col-6 mt-1 row justify-content-center">
                            <button className="btn col-11 btn-sm btn-black border-0 "
                                    onClick={() => this.props.pagehandler('0', 'read', {confirmed: false, accepted: true}, '0')}> Sin Pagar
                            </button>
                        </div> : <div/>

                    }

                    {
                        ( this.props.modules === 'cashin')? <div className="col-6 mt-1  row justify-content-center">
                            <button className="btn col-11 btn-sm btn-black border-0 "
                                    onClick={() => this.props.pagehandler('0', 'read', {confirmed: true, accepted: true}, '0')}> Compras
                            </button>
                        </div> : <div/>

                    }


                    {
                        ( this.props.modules === 'cashin' && includes(this.props.role, 'admin'))? <div className="col-6 mt-1 row justify-content-center">
                            <button className="btn col-11 btn-sm btn-black border-0"
                                    onClick={() => this.props.pagehandler('0', 'read', {type: 'Taller'}, '0')}> Taller
                            </button>
                        </div> : <div/>

                    }

                    {
                        this.props.modules === 'promotion' ? <div className="col-6 mt-1 row justify-content-center">
                            <button className="btn col-11 btn-sm btn-black border-0 "
                                    onClick={() => this.props.pagehandler('0', 'read', {label: 'Tarjeta'}, '0')}> Tarjetas
                            </button>
                        </div> : <div/>
                    }
                    {
                        this.props.modules === 'product' ? <div className="col-6 mt-1 row justify-content-center">
                            <button className="btn col-11 btn-sm btn-black border-0 "
                                    onClick={() => this.props.pagehandler('0', 'read', {category: 'Tienda'}, '0')}> Tienda
                            </button>
                        </div> : <div/>
                    }


                </div>
            </div>
        );
    }
}

export default Sections;
