import {call, put, select} from 'redux-saga/effects';
//import {serverSuccess} from '../../actions/common'
import Http from '../../services/http'


const extractArray = (result) => {
    let extracted = []

    for(const i in result){
        const item = result[i]
        const vector = item._id
        extracted = {
            ...extracted,
            [vector]: item
        }
    }
    return extracted
}

const mergeFromExtractedValues = (csv, apResult, productResult, dictionary) => {
    let cashin = csv
    const extractedAp = extractArray(apResult)
    const extractedProduct = extractArray(productResult)
    let salesByProduct = dictionary
    let salesByCreator = {}
    for(const i in csv){
        if(salesByCreator[csv[i].creator] ){
            salesByCreator[csv[i].creator] = {
                value: salesByCreator[csv[i].creator].value + csv[i].total,
                label: csv[i].creatorAlias[0].nickname
            }
        } else {
            salesByCreator[csv[i].creator] = {
                value: csv[i].total,
                label: csv[i].creatorAlias[0].nickname
            }
        }

        const productsList = csv[i].products;

        for(const j in productsList){

            const prod = productsList[j].product
            const ap = productsList[j].ap

            cashin[i].products[j] = {
                ...cashin[i].products[j],
                productName: extractedProduct[prod] ? extractedProduct[prod].name : 'NO ENCONTRADO',
                apName: extractedAp[ap] ? extractedAp[ap].label : '???',
                value:  parseFloat(cashin[i].products[j].value)
            }

            //TODO::VECTOR
            const vector = prod+'-'+ap
            //TODO::VECTOR
            if(salesByProduct[vector]){
                salesByProduct[vector] = {
                    value: ((salesByProduct[vector].value ? parseFloat(salesByProduct[vector].value) : 0) + (parseFloat(productsList[j].value) * productsList[j].apValue * productsList[j].amount)),
                    label: (extractedProduct[prod] ? extractedProduct[prod].name : 'NO ENCONTRADO')+'-'+(extractedAp[ap] ? extractedAp[ap].label : '???')
                }
            }else{
                salesByProduct[vector] = { value: ((parseFloat(productsList[j].value) * productsList[j].apValue * productsList[j].amount)), label: prod-ap}
            }


        }

    }
   return [salesByProduct, salesByCreator, cashin]
}


const generateDictionary = (csv) => {
    let dictionary = {}
    for(const i in csv){
        const productsList = csv[i].products;
        for(const j in productsList){
            const prod = productsList[j].product
            const ap = productsList[j].ap
            const vector = prod+'-'+ap
            if(!dictionary[vector]) {
                dictionary[vector] = {
                    product: prod,
                    ap: ap,
                    amount: productsList[j].amount,
                    value: productsList[j].value,
                    apValue: productsList[j].apValue
                }
            }
    }}

    return dictionary
}

const extractAndCall = async (csv, session) => {
    const dictionary = generateDictionary(csv)
    const productIds = []
    const apIds = []
    for(const key in dictionary){
        productIds.push(dictionary[key].product)
        apIds.push(dictionary[key].ap)
    }

    const endpointToSearchModule = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY;
    const apList = await Http.post((endpointToSearchModule + 'ap/read'), {_id: apIds}, session.token)
    const productList = await Http.post((endpointToSearchModule + 'product/read'), {_id: productIds}, session.token)
    return mergeFromExtractedValues(csv, apList.message, productList.message, dictionary)

}


export default function* homeRequested({request}) {
    try {

        const endpointToSearchModule = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY+ 'read/';
        const session = yield select(state => state.SESSION.session);
        const apiCall = yield call(Http.post, endpointToSearchModule, request, session.token)



        if(!apiCall.isError){
            const sells = yield call(extractAndCall, apiCall.message.csv, session)

            //const sellByProducts =  yield call(sellByProduct,apiCall.message.csv,  session.token)
            const payload = {
                isError: false,
                message: {
                    ...apiCall.message,
                    ['sellByProducts']: sells[0],
                    ['sellByCreator']: sells[1],
                    ['csv']: sells[2],
                }
            }
            yield put({type: "SERVER_SUCCESS", payload})
            // yield put(serverSuccess(payload))
            }
        else{
            yield put({type: "SERVER_FAILED"})
        }
    } catch (err) {
        console.log(err, 'ERROR');
        yield put({type: "SERVER_FAILED"});
    }
}
