const validateArrayList = (validate, values) =>{
   return map(validate,  (item) => {
        const evaluate = new Function(item.arguments, item.body)
        const evaluateValues = safellyCallFromFunc(evaluate, values,item.body)
        if (evaluateValues) {
            return {
                name: item.target,
                message: item.message,
                value: evaluate(values),
                eval: evaluate
            }
        }
    }).filter(item=>{return item !== undefined})
}



