import React, {Component} from 'react'
import {filter, find, map} from "lodash";
import Loading from "../Loading";
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";
import {saveDraftRequest} from "../../../store/actions/common";
import {recalculateTotal, recalculatePromotions} from "../../../store/services/calculateTotal"
import {getFromApi} from "../../../store/services/getFromApiSimple";


class CashInFront extends Component {
    constructor(props) {
        super(props);
        this.state = {
            values: [],
            options: [],
            optionsSecond: [],
            searchValue: '',
            searching: false
        }
    }

    async componentDidMount() {
        const {savedFromDraft, modules, name} = this.props;
        const values = savedFromDraft[modules][name]

        if (values && values.length > 0 && values[0] !== '') {
            this.setState({searching: true})
            const sourceProduct = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + this.props.extra[3]
            const sourceAp = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + this.props.extra[7] + '/read'
            let idProduct = [];
            let idAp = []
            map(this.props.value, (itm) => {
                idProduct = [...idProduct, itm.product];
                idAp = [...idAp, itm.ap]
            })
            const responseProduct = await getFromApi(sourceProduct, {_id: idProduct}, this.props.token).then((itm) => {
                return (itm.message)
            }, () => {
                return {label: "No encontrado", value: 'default'}
            })
            const responseAp = await getFromApi(sourceAp, {_id: idAp}, this.props.token).then((itm) => {
                return (itm.message)
            }, () => {
                return {label: "No encontrado", value: 'default'}
            })
            let state = []
            for (const i in this.props.value) {
                const ap = find(responseAp.message, (obj) => {
                    return obj._id === this.props.value[i].ap
                })
                state = [...state,
                    {
                        product: find(responseProduct.message, (obj) => {
                            return obj._id === this.props.value[i].product
                        }),
                        ap: ap,
                        apValue: this.props.value[i].apValue ? this.props.value[i].apValue : ap.value,
                        value: this.props.getter(this.props.extra[1])[i].value,
                        amount: this.props.getter(this.props.extra[1])[i].amount ? this.props.getter(this.props.extra[1])[i].amount : 1

                    }

                ]
            }
            this.setState({values: state, searching:false})
        }
    }

    async handleSearch(e) {
        const source = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + this.props.extra[3]
        if (e.target.value.length > 1) {
            this.setState({searching: true, searchValue: e.target.value, options: [], optionsSecond: []})
            const response = await getFromApi(source, {[this.props.extra[4]]: e.target.value}, this.props.token).then(
                (itm) => {
                    return (itm.message)
                },
                () => {
                    return false
                })
            if(response) {
                this.setState({
                    options: !response ? {label: "No encontrado", value: 'default'} : response.message,
                    searching: false
                })
            } else {
                this.setState({
                    options:  [] ,
                    optionsSecond: [],
                    searching: false
                })
            }
        }
    }

    async handleFirstSelect(e) {
        const source = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + this.props.extra[7] + '/read'
        const response = await getFromApi(source, {_id: this.state.options[e.target.value][this.props.extra[7]]}, this.props.token).then(
            (itm) => {
                return (itm.message)
            },
            () => {
                return {label: "No encontrado", value: 'default'}
            })
        this.setState({searching: true})
        if(response) {
            this.setState({optionsSecond: response.message, [e.target.name]: e.target.value, searching: false});
        }

    }

    handleSecondSelect(e) {
        this.setState({[e.target.name]: e.target.value})
    }

    handleAdd() {
        const {savedFromDraft, modules, extra, onChangeValue} = this.props;
        const {options, searching, optionsSecond} = this.state;
        const apName = this.state[extra[7]]
        const productName = this.state[extra[8]]


        if (options.length > 0 && !searching && optionsSecond[apName] && options[productName]) {
            this.setState((prevState) => {
                const newProductsArray = [
                    ...(prevState.values || []),
                    {
                        product: options[productName],
                        ap: optionsSecond[this.state[extra[7]]],
                        value: options[productName].value,
                        apValue: optionsSecond[apName].value,
                        amount: 1,
                    },
                ];

                let newProducts = map(newProductsArray, (itm) => {
                    return {
                        product: itm.product._id,
                        ap: itm.ap._id,
                        value: itm.value,
                        amount: itm.amount,
                        apValue: itm.apValue,
                    };
                });
                //total

                onChangeValue({
                    [extra[1]]: newProducts,
                    ['promotion']: recalculatePromotions(newProducts,savedFromDraft[modules]['promotion']),
                    [extra[5]]: recalculateTotal(newProducts, savedFromDraft[modules]['promotion'])
                })

                return {
                    values: [...prevState.values, {
                        [this.props.extra[7]]: this.state.optionsSecond[apName],
                        [this.props.extra[8]]: this.state.options[productName],
                        value: this.state.options[productName].value,
                        apValue: this.state.optionsSecond[apName].value,
                        amount: 1,
                    }

                    ]
                }
            })
        }

    }

    handleValueChange(v, n) {
        const {savedFromDraft, modules, extra, onChangeValue} = this.props;
        const name = n
        const value = v

        this.setState(
            (prevState) => {

                let state = prevState.values
                state[name].value = value
                const newProducts = map(state, (itm) => {
                    return {
                        product: itm.product._id,
                        ap: itm.ap._id,
                        apValue: itm.ap.value,
                        value: itm.value,
                        amount: itm.amount
                    }
                })
                onChangeValue({
                    [extra[1]]: newProducts,
                    ['promotion']: recalculatePromotions(newProducts,savedFromDraft[modules]['promotion']),
                    [extra[5]]: recalculateTotal(state, savedFromDraft[modules]['promotion'])
                })
                return {
                    values: state
                }
            }
        )
    }

    handleDelete(e) {
        //here
        const {savedFromDraft, modules, extra, onChangeValue} = this.props;
        this.setState((prevState) => {
                const newValues = filter(prevState.values, (itm, ind) => {
                    return ind !== e
                })
                const newValuesNormalized = map(newValues, (itm) => {
                    return {
                        product: itm.product._id,
                        ap: itm.ap._id,
                        value: itm.value,
                        amount: itm.amount,
                        apValue: itm.apValue
                    }
                })

                onChangeValue({
                    [extra[1]]: newValuesNormalized,
                    [extra[5]]: recalculateTotal(newValuesNormalized, savedFromDraft[modules]['promotion'])
                })
                return {
                    values: newValues
                }
            }
        )


    }

    addOrTakeFromQuantityItem(option, ind, amount) {
        const {savedFromDraft, modules, extra, onChangeValue} = this.props;
        this.setState((prevState) => {
            const state = prevState;
            state.values[ind].amount = amount + (option ? 1 : amount > 1 ? -1 : 0)
            const newProducts = map(state.values, (itm) => {
                return {
                    product: itm.product._id,
                    ap: itm.ap._id,
                    value: itm.value,
                    amount: state.values[ind].amount,
                    apValue: itm.apValue
                }
            })

            onChangeValue({
                [extra[1]]: newProducts,
                [extra[5]]: recalculateTotal(state.values, savedFromDraft[modules]['promotion'])
            })

            return state
        })
    }

    updateAp(item, index) {
        this.setState((prevState) => {
            const {savedFromDraft, modules, extra, onChangeValue} = this.props;

            let state = prevState;
            state.values[index].apValue = parseInt(item.ap.value)
            const newProducts = map(state.values, (itm) => {
                return {
                    product: itm.product._id,
                    ap: itm.ap._id,
                    value: itm.value,
                    amount: itm.amount,
                    apValue: itm.ap.value
                }
            })
            onChangeValue({
                [extra[1]]: newProducts,
                [extra[5]]: recalculateTotal(state.values, savedFromDraft[modules]['promotion'])
            })

            return state
        })
    }

    render() {
        const {extra} = this.props;
        const { optionsSecond, searching, values} = this.state;
        return (
            <div className="row p-0 m-0 ">
                <div>
                    <div className="row mb-3">
                            <input type="text"
                                   placeholder="Escribir Para Buscar"
                                   name="Buscador de productos"
                                   onChange={(e) => this.handleSearch(e)}/>
                    </div>
                </div>

                {searching ? <Loading size={'sm'} label={'Cargando'}/> :
                    <div style={{border: '2px solid red', borderRadius: '15px'}} className=" bg-black row col-12 p-0 m-0 pb-3 pt-1 justify-content-center align-items-center">
                        <div className="row col-lg-6 col-sm-12 justify-content-center align-items-center">
                            <div className=" swing-in-top-fwd row mt-2">
                                <select
                                    name={this.props.extra[8]}
                                    placeholder="seleccione"
                                    onChange={(e) => this.handleFirstSelect(e)}>
                                    <option value="default">{this.state.searching ? 'Cargando' : (this.state.options.length > 0 ? 'Seleccione el Producto' : 'Buscar')}</option>
                                    {map(this.state.options, (itm, ind) => {
                                        return (
                                            <option value={ind} key={ind}> {itm.name} - {itm.category}</option>
                                        )
                                    })}
                                </select>
                            </div>
                        </div>
                        <div className="row col-lg-6 col-sm-12 justify-content-center align-items-center">
                            <div className="swing-in-top-fwd row mt-2 list-style">
                                <select name={extra[7]} onChange={(e) => this.handleSecondSelect(e)}>
                                    <option
                                        value="default">{searching ? 'Cargando' : (optionsSecond.length > 0 ? 'Seleccione el Ap' : 'Buscar')}</option>
                                    {map(optionsSecond, (itm, ind) => {
                                        return (
                                            <option value={ind} key={ind}> {itm.label} - {itm.value}</option>)
                                    })}

                                </select>
                            </div>
                        </div>
                        <div className="row col-12 justify-content-center align-items-center">
                            <div className="swing-in-top-fwd row mt-4 justify-content-center">
                                <div className="row col-6">
                                    <button className="btn btn-danger "
                                            onClick={() => this.handleAdd()}>Agregar
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                }
                <div className="row col-12 justify-content-center p-0 m-0 mt-1 ">
                    {values.length > 0 ?
                        map(values, (itm, ind) => {
                            return (
                                <div style={{border: '2px solid red', borderRadius: '15px'}}
                                     className="swing-in-top-fwd p-0 m-0 mt-4 p-3 fs-6 custom-select-multiple row col-12 bg-black"
                                     key={ind}>
                                    <div className="col-sm-12 col-lg-6 row justify-content-center align-content-center p-0 m-0">
                                        <div className="col-6 row justify-content-center align-content-center p-0 m-0">
                                            <div className="col row row justify-content-evenly ">
                                                <div
                                                    className="row col-sm-12 col-lg-4 justify-content-center p-0 m-0 mt-2">
                                                    <button className=" btn btn-sm btn-danger col-sm-8 col-lg-6"
                                                            value={(parseInt(itm.value) + 1)}
                                                            name={ind}
                                                            onClick={() => this.handleValueChange(parseInt(itm.value + (1)), ind)}>
                                                        <i className="bi bi-plus "/>
                                                    </button>
                                                </div>
                                                <div
                                                    className="row col-sm-12 col-lg-4 justify-content-center align-content-center p-0 m-0 mt-2">
                                                    <input className="row btn btn-sm btn-dark fs-5 col-sm-12 col-lg-8"
                                                           value={itm.value} type="number"
                                                           name={ind}
                                                           onChange={(e) => this.handleValueChange(e.target.value, ind)}/>
                                                </div>
                                                <div
                                                    className="row col-sm-12 col-lg-4 justify-content-center p-0 m-0 mt-2">
                                                    <button
                                                        className=" btn btn-sm btn-danger col-sm-8 col-lg-5 row fw-bold"
                                                        value={(parseInt(itm.value) - 1)}
                                                        name={ind}
                                                        onClick={() => this.handleValueChange(parseInt(itm.value + (-1)), ind)}>
                                                        <i className="bi bi-dash "/>
                                                    </button>
                                                </div>

                                            </div>
                                        </div>
                                        <div className="col-6 row justify-content-center align-content-center p-0 m-0 ">
                                            <div className="row col-sm-12 col-lg-6 justify-content-center p-0 m-0 mt-3">
                                                <div className="btn btn-sm btn-danger col-6 row "
                                                     onClick={() => this.addOrTakeFromQuantityItem(true, ind, itm.amount)}>
                                                    <i className="bi bi-plus "/>
                                                </div>
                                            </div>
                                            <div className="row col-sm-12 col-lg-6 justify-content-center p-0 m-0 mt-3">
                                                <button className=" btn btn-sm btn-danger col-6 row fw-bold"
                                                        onClick={() => this.addOrTakeFromQuantityItem(false, ind, itm.amount)}>
                                                    <i className="bi bi-dash "/>
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="col-12 row justify-content-center align-content-center p-0 m-0 mt-3 ">
                                        <div className="col-sm-12 col-lg-6 row p-0 m-0">
                                            <div className="col-sm-12 col-lg-6 row justify-content-around align-content-center p-0 m-0 ">
                                                <div className="row col-4 justify-content-center align-content-center p-0 m-0">
                                                    <div className="row col-6 justify-content-center align-content-center p-0 m-0 ">
                                                        Producto:
                                                    </div>
                                                </div>
                                                <div className="row col-6 justify-content-center align-content-center p-0 m-0 ">
                                                    <div className="row col-12 justify-content-center align-content-center p-0 m-0">
                                                        <div className="btn btn-sm btn-outline-danger p-0 m-0 fw-bold" style={{fontSize: '0.8rem'}}>
                                                            {itm.product && itm.product.name ? itm.product.name : 'No Encotrado BORRAR'} - {itm.value}
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="col-sm-12 col-lg-6 row justify-content-around align-content-center p-0 m-0 ">
                                                <div className="row col-4 justify-content-center align-content-center p-0 m-0">
                                                    <div
                                                        className="row col-6 justify-content-center align-content-center p-0 m-0 ">
                                                        Cantidad:
                                                    </div>
                                                </div>
                                                <div className="row col-6 justify-content-center align-content-center p-0 m-0 ">
                                                    <div
                                                        className="row col-12 justify-content-center align-content-center p-0 m-0">
                                                        <div className="btn btn-sm btn-outline-danger p-0 m-0 fw-bold"
                                                             style={{fontSize: '0.8rem'}}>{itm.amount}</div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="col-sm-12 col-lg-6 row p-0 m-0  ">
                                            <div className="col-sm-12 col-lg-6 row justify-content-around align-content-center p-0 m-0 mt-lg-0 mt-3">
                                                <div className="row col-4 justify-content-center align-content-center p-0 m-0 mt-sm-5 mt-lg-0">
                                                        <div className="row col-12 justify-content-center align-content-center p-0 m-0" style={{fontSize: '0.8rem'}}>
                                                            <div className="row col-2 justify-content-center align-content-center p-0 m-0 ">
                                                                AP:
                                                            </div>
                                                            <div className="row col-auto justify-content-start align-content-center p-0 m-0">
                                                                {itm.ap && itm.ap.label ? itm.ap.label : 'No encontrado BORRAR'}
                                                            </div>
                                                        </div>
                                                </div>
                                                <div className="row col-6 justify-content-center align-content-center p-0 m-0 mt-sm-5 mt-lg-0 ">
                                                    <div className="row col-12 justify-content-center align-content-center p-0 m-0">
                                                        <div className=" p-0 m-0 fw-bold" style={{fontSize: '0.8rem'}}>
                                                            <div className="row col-sm-12 col-lg-6 justify-content-center align-content-center p-0 m-0">
                                                                <div className="row col justify-content-center align-content-center p-0 m-0 ">
                                                                    {itm.ap && !(itm.ap.value === itm.apValue) ?
                                                                        <div className="row col-12 justify-content-center align-content-center p-0 m-0 ">
                                                                            <div className="row col-12 justify-content-center align-content-center  p-0 m-0">
                                                                                <div className="row col btn btn-sm btn-dark  p-0 m-0" style={{fontSize: '0.8rem'}}>
                                                                                    {itm.apValue}
                                                                                </div>
                                                                            </div>
                                                                            <div
                                                                                className="row col-12 justify-content-center align-content-center  p-0 m-0">
                                                                                <div
                                                                                    className="row col btn btn-sm btn-danger justify-content-center align-content-center  p-0 m-0"
                                                                                    onClick={() => {
                                                                                        this.updateAp(itm, ind)
                                                                                    }} style={{fontSize: '0.8rem'}}>
                                                                                    {itm.ap.value}
                                                                                </div>
                                                                            </div>
                                                                        </div> :
                                                                        <div
                                                                            className="row col-12 justify-content-center align-content-center p-0 m-0">
                                                                            <div
                                                                                className="row col btn btn-sm btn-dark p-0 m-0"
                                                                                style={{fontSize: '0.8rem'}}>
                                                                                {itm.apValue}
                                                                            </div>
                                                                        </div>
                                                                    }
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="col-sm-12 col-lg-6 row justify-content-center align-content-center p-0 m-0 mt-lg-0 mt-3">
                                                <div
                                                    className="row col-sm-12 col-lg-12 justify-content-center align-content-center p-0 m-0">
                                                    <div
                                                        className="row col-6 justify-content-space align-content-center p-0 m-0">
                                                        <div
                                                            className="row col justify-content-center align-content-center p-0 m-0">
                                                            Total:
                                                        </div>
                                                        <div
                                                            className="row col justify-content-center align-content-center p-0 m-0 ">
                                                            <div
                                                                className="fw-bold col-6 row p-0 m-0 justify-content-center"
                                                                style={{borderBottom: '3px solid yellow'}}>
                                                                {(itm.value * ((itm.apValue || !(itm.apValue !== itm.ap.value)) ? itm.apValue : itm.ap.value) * itm.amount).toString(10).split('.')[0]}
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <div
                                                        className="row col justify-content-center align-content-center p-0 m-0">
                                                        <div className=" btn btn-sm btn-danger col-10 row "
                                                             onClick={() => this.handleDelete(ind)}>
                                                            <i className="bi bi-trash"/>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )
                        })  : <div/>}
                </div>

                <div className="row col-12 justify-content-center p-0 m-0 mt-1 ">
                    <div className="row col-12 justify-content-center p-0 m-0 ">
                        <div className="row col-6 justify-content-center p-0 m-0 justify-content-center align-content-center" style={{fontSize: '0.8rem'}}>Total de Productos:</div>
                        <div className="row col-6 justify-content-center p-0 m-0" >
                            <div className="row col-6 justify-content-center p-0 m-0 justify-content-center align-content-center"
                                 style={{color: 'yellow', backgroundColor: 'red', borderRadius: '5px'}}>
                                {recalculateTotal(this.state.values, this.props.savedFromDraft[this.props.modules]['promotion'])}
                            </div>
                        </div>
                    </div>
                </div>
            </div>


        )
    }

}

export default connect(
    (state) => ({
        table: state.UMODULE,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload,
        token: state.SESSION.session.token,
    }),
    (dispatch) => ({
        saveDraft: (payload) => dispatch(saveDraftRequest(payload))
    })
)(withRouter(CashInFront));


