import React, {Component} from "react";
import {map} from "lodash";
import {Link, withRouter} from "react-router-dom";
import {connect} from "react-redux";


class  NavBar extends Component{
    constructor(props) {
        super(props);
        this.state = {
            showingMenu: false,
            showingNotificationModal: false,
        }
    }

    handleHide(){
        this.setState((prevState)=>{
            return {
                showingMenu: !prevState.showingMenu
            }
        })
    }
    handleNotification(){
        this.setState((prevState)=>{
            return {
                showingNotificationModal: !prevState.showingNotificationModal
            }})
    }


    render() {
        const nickname = this.props.session.profile.nickname
        return (
            <div className={'menuDash p-0 m-0 '}>
                    <div className="row col-12 p-0 m-0 justify-content-center align-items-center">
                        <div className="row col-12 justify-content-center align-items-center p-0 m-0 mt-3">


                                <div className="row col-8 justify-content-center align-content-center p-0 m-0 pr-1">
                                    <Link to={'/'} className="row col-6 text-decoration-none text-white p-0 m-0">
                                            {nickname}
                                        </Link>
                                </div>

                                <div className="row col-4  justify-content-end align-content-center p-0 m-0 ">
                                    <div className="row col-6 p-0 m-0 justify-content-center">
                                        <div className="row col-6 justify-end align-content-start  p-0 m-0">
                                            <i className="row col-12  justify-content-end bi fs-1 bi-list bold p-0 m-0 fw-bold text-white"
                                               onClick={e => this.handleHide(e)}></i>
                                        </div>
                                    </div>
                                </div>



                        </div>




                        <div  className="row col-12 justify-content-center align-items-center menu-custom" >

                            {this.state.showingMenu && this.props.routes ?
                                <ul className={"row justify-content-center align-content-center menu-custom"}>
                                    {map(this.props.routes, (itm, key) => {
                                        return (<li key={key}
                                                className={"col-sm-4 row justify-content-center swing-in-top-fwd"}>
                                                <Link key={key}
                                                      className={'m-3 fw-bold swing-in-top-fwd text-decoration-none col justify-content-center col row justify-content-center align-content-center'}
                                                      to={itm === 'Home' ? '' : itm}>
                                                    <button
                                                        className={'row btn rounded-2 bg-danger text-white fw-bold '}
                                                        onClick={e => this.handleHide(e)}>
                                                        {itm}
                                                    </button>
                                                </Link>
                                            </li>)})}
                                </ul> : <div className="d-none"/>}

                        </div>
                    </div>
            </div>
        )
    }
}

export default connect(
    state => ({
        session: state.SESSION.session,
    })
)(withRouter(NavBar))
