import React from 'react';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import {map} from "lodash";

ChartJS.register(
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend
);






export default class BarChart extends React.Component {
    constructor(props) {
        super(props);
    }
    render() {

        const labels = map(this.props.data, (item) => item.label)

        const dataset = map(this.props.data, (item) => item.value)
        const data = {
            labels,
        datasets: [{
            label: 'Valor $$$',
            data: dataset,
            backgroundColor: 'red',
            borderColor: 'red',
            borderWidth: 1,
        }]
    };
        return (
            <div>
                <Bar data={data} />
            </div>
        );
    }
}
