import React, {Component} from 'react';
import {map, filter} from "lodash";
import {connect} from "react-redux";
import {saveDraftRequest} from "../../../store/actions/common";
import {withRouter} from "react-router-dom";

class RolePicker extends Component {
    constructor(props) {
        super(props);
        this.state = {
            values : this.props.value,
            selected: 'admin'
        }
    }


    handleSelect(){
        const { name, onChangeValue } = this.props;
        this.setState((prevState)=>{
            let state = []
            let value = prevState.selected
            state = prevState.values
            if(state.length > 0){
                state = [...state , value]
            } else {
                state = [value]
            }

            onChangeValue({[name]: state})
            return {values: state}
            }
        )


    }

    handleDelete(key){
        const { name, onChangeValue } = this.props;
        this.setState((prevState)=>{
            let state = filter(prevState.values, (item)=>{
                return item !== prevState.values[key]

            })
            onChangeValue({[name]: state})
            return {values: state}

        })


    }

    handleValue(e){
        this.setState({
            selected: e.target.value
        })
    }
    render() {
        return (
            <div className="row col-12">


                <div className="row col-12 justify-content-center align-items-center">
                    <div className="col-10">
                        <select name={this.props.name}  onClick={(e)=>this.handleValue(e)}>
                            {map(this.props.extra[3], (option, key)=>{
                                return (<option  value={option} key={key}>{option}</option>)
                            })}
                        </select>
                    </div>
                    <div className="col">
                        <button className="btn btn-danger" value={this.state.selected} onClick={()=>this.handleSelect()}> Agregar </button>
                    </div>
                </div>
                {this.state.values ?
                <div className="row col-12">
                    {map(this.state.values, (value, key)=>{
                    return <div key={key} className="row col-12">
                        <div className="col-8 bg-black row justify-content-center">
                            {value}
                        </div>
                        <div onClick={()=>this.handleDelete(key)} className="row col-2 bg-danger justify-content-center">
                            x
                        </div>
                    </div>
                    })}
                    </div> : <div/>

                }
            </div>
        );
    }
}


export default connect(
    (state) => ({
        table: state.UMODULE,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload,
        token: state.SESSION.session.token,
    }),
    (dispatch) => ({
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload))})
)(withRouter(RolePicker));
