

import { put, call, select} from 'redux-saga/effects';
import Http from '../services/http'
import {map} from 'lodash'



const getDefaultHeaders = (mode, compList, values) =>{
    let types = {}
    let indexes = {}
    if (mode === 'update' || mode === 'delete') {
        indexes = {_id: ''}

    }
    let heads = map(compList, (item) => {
        if ((!(item[0] === 'chapter' || item[0] === 'label' || item[0] === ''))) {
            types = {...types, [item[1]]: item[0]}
            return item[1]
        }
    })

    if (mode === 'update' || mode === 'delete') {
        heads[heads.length] = '_id'

    }
    for (const i in heads) {
        if (heads[i]) {
            if (values) {
                indexes[heads[i]] = values[heads[i]] ? values[heads[i]] : getDefaultValue(types, heads[i])
            } else {
                indexes[heads[i]] = getDefaultValue(types, heads[i])
            }

        }
    }
return indexes


}
const getDefaultValue = (types, keys)=>{
    switch (types[keys]) {
        case 'number': return 1;
        case 'text': return '';
        case 'checkbox': return false;
        case 'mdEditor': return '';
        case 'selectMultipleCustom': return [];
        case 'selectMultipleSimple': return [];
        case 'selectPerson': return 'Vacio';
        case 'select': return 'Tienda';
        case 'percentage':return 1;
        case 'rolePicker':return [];
        default: return ''
    }


}
export default function* uModuleRequested({payload}) {
    try {
        yield put ({type: 'UMODULE_RESET_CUD'})
        yield put({type: "SAVE_DRAFT_RESET"})
        yield put({type: "UNIVERSAL_FETCH_RESET"})
        const {modules, body, values, mode} = payload
        const skip = '?skip=' + ( body.skip === '0' ? '0' : (body.skip ?  body.skip : '0' ))
        const uModule = yield select(state => state.UMODULE);
        const pastModules = uModule.payload;
        const endpointToSearchModule = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + modules + '/read/' + skip
        const session = yield select(state => state.SESSION.session);
        let apiCall = {
            isError: true
        }
        if (uModule.sending) {
            apiCall = yield call(Http.post, endpointToSearchModule,  values, session.token)
        }
        if (!apiCall.isError) {
            const indexes = getDefaultHeaders(mode, body.compList, values)
            const payloads = {values: indexes, modules: modules}
            yield put({type: "SAVE_DRAFT_REQUEST", payload:payloads})
            yield put({type: 'UMODULE_SUCCESS',payload:({...pastModules,[modules]: {...apiCall, last: payload}})})
        }
    }
        catch (err) {
        yield put({type: "UMODULE_FAILED"});
    }
}

