import React, {Component} from "react";
import {find, map} from "lodash";
import {connect} from "react-redux";
import {saveDraftRequest} from "../../../store/actions/common";
import {withRouter} from "react-router-dom";
import {getFromApi} from "../../../store/services/getFromApiSimple";





class DeletePaymentChoose extends Component {
    constructor(props) {
        super(props);
        const {savedFromDraft, modules, name} = this.props;
        this.state = {
            options: [],
            values: savedFromDraft[modules][name],
            selectInput: 'default'
        }

    }

    async componentDidMount() {
        const {savedFromDraft, modules, name} = this.props;
        const values = savedFromDraft[modules][name]

        if (values && values.length > 0 && values[0] !== '') {
            this.setState({searching: true})
            const sourceProduct = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + this.props.extra[3]
            const sourceAp = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + this.props.extra[7] + '/read'
            let idProduct = [];
            let idAp = []
            map(this.props.value, (itm) => {
                idProduct = [...idProduct, itm.product];
                idAp = [...idAp, itm.ap]
            })
            const responseProduct = await getFromApi(sourceProduct, {_id: idProduct}, this.props.token).then((itm) => {
                return (itm.message)
            }, () => {
                return {label: "No encontrado", value: 'default'}
            })
            const responseAp = await getFromApi(sourceAp, {_id: idAp}, this.props.token).then((itm) => {
                return (itm.message)
            }, () => {
                return {label: "No encontrado", value: 'default'}
            })
            let state = []
            for (const i in this.props.value) {
                const ap = find(responseAp.message, (obj) => {
                    return obj._id === this.props.value[i].ap
                })
                state = [...state,
                    {
                        product: find(responseProduct.message, (obj) => {
                            return obj._id === this.props.value[i].product
                        }),
                        ap: ap,
                        apValue: this.props.value[i].apValue ? this.props.value[i].apValue : ap.value,
                        value: this.props.getter(this.props.extra[1])[i].value,
                        amount: this.props.getter(this.props.extra[1])[i].amount ? this.props.getter(this.props.extra[1])[i].amount : 1

                    }

                ]
            }
            this.setState({values: state})
        }
    }

    render() {
        const { values} = this.state;
        const {extra, savedFromDraft, modules, name} = this.props;
        if(savedFromDraft[modules][name]){
            return (
                <div className={"row justify-content-center p-0 m-0 "}>
                    {//showing only if there is a payment method
                        savedFromDraft[modules][name] ?
                            <div className="row col-12 p-0 m-0 mt-1 justify-content-center align-content-center">
                                {map(values, (value, index)=>{
                                        return (
                                            <div style={{border: '2px solid red', borderRadius: '15px'}} key={index} className="row col-sm-12 col-lg-10 justify-content-space align-content-sm-between bg-black p-1 m-0 mt-1">
                                                <div className="col-6 row text-white fs-6 justify-content-center align-content-center p-0 m-0 ">
                                                    {map(extra[4], (itm)=>{
                                                            if (itm=== 'label'){
                                                                return value[itm]
                                                            } else {
                                                                return ('  ' +value[itm] +' : ' +value.total)
                                                            }
                                                        }
                                                    )
                                                    }
                                                </div>
                                            </div>
                                        )
                                    }
                                )
                                }
                            </div>
                            :<div/>
                    }
                </div>
            );

        }

    }
}
export default connect(
    (state) => ({
        table: state.UMODULE,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload,
        token: state.SESSION.session.token,
    }),
    (dispatch) => ({
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload))})
)(withRouter(DeletePaymentChoose));
