import React from 'react';
import {
    Card, CardBody, CardTitle, Row
} from 'reactstrap';
import HashLoader from 'react-spinners/HashLoader';

const Loading = ({label, size, modal}) => {

    const sizeLoading = size ? size : 'sm'
    const modalView = modal ? 'makeLoadingAModalView' : ''
    return (
        <div className={"row col-12 justify-content-center align-items-center m-0 p-0 mt-5 " + modalView}>
            <Card style={{zIndex: '999999'} } className=" bg-dark row col-8">
                <CardBody>
                    <CardTitle>
                        <Row className="justify-content-center align-content-center pb-5">
                            <HashLoader
                                size={sizeLoading === 'sm' ? 40 : sizeLoading === 'md' ? 60 : 90 / 4 }
                                color='red'
                                loading
                            />
                        </Row>
                        <Row style={{justifyContent: 'center'}}>
                            {label ? label : "Cargando"}
                        </Row>
                    </CardTitle>
                </CardBody>
            </Card>
        </div>


);
}

export default Loading;
