
import React, {Component} from "react";





class ModalViewForLongText extends Component{
        constructor(props) {
            super(props);
            this.state = {
                showing: false
            }
        }
        handleShowing(e){
            e.preventDefault();
            this.setState((prevState)=>{
                return {
                    showing: !prevState.showing
                }
            })
        }
        render(){
            const {itemFromApi, itemFromTheForm} = this.props
            return (
                this.state.showing ?
                    <div className="row col justify-content-center align-items-start modalMdEditorView">
                        <div >
                            <div className="row col justify-content-center align-items-center">
                                <div className="row col justify-content-center align-items-center mt-3">
                                    <i className="bi bi-x text-white"
                                       onClick={(e) => this.handleShowing(e)}>
                                    </i>
                                </div>
                            </div>
                        </div>
                        <div className="row col-12 justify-content-center align-items-center">
                            {itemFromApi[itemFromTheForm[0]]}
                        </div>
                    </div>
                    :
                    <div className=" btn-sm text-info pt-0 pb-0"
                         onClick={(e) => this.handleShowing(e)}>
                        <i className="bi bi-chat-dots"></i>
                    </div>
            )
        }
}


const MdViewer = ({itemFromApi, itemFromTheForm}) => {
    return (

            <div className="row justify-content-center align-items-center p-0 m-0">
            <ModalViewForLongText itemFromApi={itemFromApi} itemFromTheForm={itemFromTheForm}/>
            </div>
    );

}

export default MdViewer;
