import {
    UNIVERSAL_FETCH,
    UNIVERSAL_FETCH_FAILED,
    UNIVERSAL_FETCH_RESET,
    UNIVERSAL_FETCH_SUCCESS
} from "../actions/common";

export default function UFETCH(state =
                                    {success: false, loading: false,
                                        error: false,
                                            },action) {

    switch (action.type) {
        case UNIVERSAL_FETCH_RESET:
            return {
                loading:false, error: false, success: false
            }
        case UNIVERSAL_FETCH:
            return {
                 ...state,loading: true, error: false, success: false,
            };
        case UNIVERSAL_FETCH_SUCCESS:
            return {
                ...state, success: true, loading: false, error: false, payload: action.payload
            };
        case UNIVERSAL_FETCH_FAILED:
            return {
                ...state, success: false,  loading: false, error: true, payload: action.payload
            }

        default:
            return state;
    }
}
