import { put, call, select } from 'redux-saga/effects';
import Http from '../services/http'
import { universalFetchFailed, universalFetchSucces} from "../actions/common";


export default function* universalFetchSaga({payload}) {
    try {
        const {url, body, modules, name} = payload;
        const ufetch = yield select(state => state.UFETCH);
        const endpoint = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + url
        const session = yield select(state => state.SESSION.session);
        const apiCall = yield call(Http.post, endpoint, body, session.token)

        if(ufetch.payload === undefined) {
            yield put(universalFetchSucces ({[modules]:{[name]:apiCall}}))
        }
        else {
            const newDictionaryUFetch = {
                ...ufetch.payload[modules],
                [name]: apiCall
            }
            yield put(universalFetchSucces ({[modules]:newDictionaryUFetch}))
        }

    } catch (err) {
        console.log(err)
        yield put(universalFetchFailed('Error Saga'))
    }
}
