import React, {Component} from "react";
import {connect} from "react-redux";
import {uModuleRequest} from "../../../store/actions/uModule";
import {withRouter} from "react-router-dom";
import {find, includes, map} from "lodash";
import {Error404} from "../index";
import { Table, Thead, Tbody, Tr, Th, Td } from 'react-super-responsive-table';
import HeaderSearch from "./HeaderComponent";
import Pagination from "./Pagination";
import MdViewer from "./Components/MdViewer";
import MultipleListViewer from "./Components/MultipleListViewer";


const Card = (props)=>{
    const {value} = props
    if (includes( value, 'Tarjeta') || includes( value, 'tarjeta')){
        return (
            <div>{value}
                <i style={{color: 'red'}} className="bi bi-currency-dollar"/>
                <i style={{color: 'red'}} className="bi bi-currency-dollar"/>
                <i style={{color: 'red'}} className="bi bi-currency-dollar"/>
            </div>
        )
    }
    return (
        <div>
            {value}
        </div>
    )

}


class TableList extends Component{
    constructor(props) {
        super(props);
        this.state = {
            body: null,
            skip: 0,
            table: true
        }
    }



handleView(view){
        this.setState((prevState)=>{return {[view]: !prevState[view]}})
}

render(){
        const {table, header, modules, form, prevState, handlePageCallback} = this.props;
        const {success, payload, sending} = table;

        const HeaderComponent = ()=>{
            return (
                <div className="row col-12  text-decoration-underline justify-content-center align-items-start p-0 m-0 mb-5 ">
                        <div className=" col-6  row justify-content-center fs-6" onClick={() => this.handleView('table')}>
                            Mostrar
                        </div>
                        <div className="col-6 row justify-content-center fs-6" onClick={() => this.handleView('search')}>
                            Buscar
                        </div>
                </div>
            )
        }

    const collection = this.props.table.payload[this.props.modules].message;
    return (
        <div>
            {sending ? <div>Loading</div> : (
                success || payload[modules] ? (
                    <div className={"row col-12 align-content-start p-0 m-0 "}>
                        {<HeaderComponent/>}
                        {this.state['search'] &&
                            <HeaderSearch header={header} modules={modules} prevState={prevState}
                                          readTableInformationCallback={handlePageCallback}/>
                        }
                        {this.state['table'] &&
                            <div className="row swing-in-top-fwd justify-content-center p-0 m-0">
                                <Table className="text-white fs-6 p-0 m-0 ">
                                    <Thead>
                                        <Tr>
                                            {map(header, (triplet, key) => {return (<Th className="text-white" key={key}><div>{triplet[1]}</div></Th>)})}
                                        </Tr>
                                    </Thead>
                                    <Tbody >
                                        {
                                            map(collection, (itemFromApi, itemKeyFromApi)=>{
                                                return(
                                                    <Tr key={itemKeyFromApi}>
                                                        {map(header ,(itemFromTheForm)=>{
                                                    const formComponent = find(form, (itm)=>{
                                                        return itm[1] === itemFromTheForm[0]
                                                        }
                                                    )
                                                            switch (itemFromTheForm[0]) {
                                                                case "index":
                                                                    return <Td key={itemKeyFromApi}
                                                                               className="">{(itemKeyFromApi + (this.props.table.payload[this.props.modules].last.body.skip ? this.props.table.payload[this.props.modules].last.body.skip * 11 : 1))}</Td>
                                                                case "createdAt":
                                                                    return <Td key={itemKeyFromApi}
                                                                               className="">{new Date(itemFromApi[itemFromTheForm[0]]).toISOString().toString().split('T')[0].replaceAll('-','/').split('/').reverse().join('/')}</Td>
                                                                case "updatedAt":
                                                                    return <Td key={itemKeyFromApi}
                                                                               className="">{new Date(itemFromApi[itemFromTheForm[0]]).toISOString().toString().split('T')[0].replaceAll('-','/').split('/').reverse().join('/')}</Td>
                                                                case 'UPDATE':
                                                                    return <Td key={itemKeyFromApi}
                                                                    >
                                                                        <button
                                                                            className="btn text-success border-0  m-0"
                                                                            onClick={() => this.props.onUpdateValues(itemFromApi)}>
                                                                            <i className="bi bi-pencil-square fs-6"></i>
                                                                        </button>
                                                                    </Td>
                                                                case 'DELETE':
                                                                    return <Td key={itemKeyFromApi}>
                                                                        <button className="btn border-0 m-0 " onClick={() => this.props.onDeleteValues(itemFromApi)}>
                                                                            <i className="bi bi-trash text-danger fs-6"></i>
                                                                        </button>
                                                                    </Td>
                                                                default: {
                                                                    switch (itemFromTheForm[2]) {
                                                                        case 'checkbox':
                                                                            return <Td key={itemKeyFromApi}><i
                                                                                className="bi bi-gem fs-3"
                                                                                style={itemFromApi[itemFromTheForm[0]] ? {color: 'red'} : {color: 'white'}}></i></Td>
                                                                        case 'combo':
                                                                            return <Td key={itemKeyFromApi}> {
                                                                                <MultipleListViewer
                                                                                formComponent={formComponent}
                                                                                token={this.props.token}
                                                                                itemFromApi={itemFromApi}
                                                                                itemFromTheForm={itemFromTheForm}
                                                                                itemKeyFromApi={itemKeyFromApi}
                                                                            />
                                                                            } </Td>
                                                                        case 'alias':
                                                                            return <Td key={itemKeyFromApi}>
                                                                                {itemFromApi[itemFromTheForm[0] + 'Alias'].length > 0 ? itemFromApi[itemFromTheForm[0] + 'Alias'][0].nickname : '-'}
                                                                            </Td>
                                                                        case 'markdown':
                                                                            return <Td key={itemKeyFromApi}><MdViewer
                                                                                itemFromApi={itemFromApi}
                                                                                itemFromTheForm={itemFromTheForm}
                                                                                itemKeyFromApi={itemKeyFromApi}/>
                                                                        </Td>
                                                                        case 'percentage':
                                                                            return <Td key={itemKeyFromApi}
                                                                                className={'p-0 m-0 m-2'}>{((1 - parseFloat(itemFromApi[itemFromTheForm[0]])) * 100 * -1).toFixed(2)}</Td>

                                                                        case 'card':
                                                                            return <Td key={itemKeyFromApi}
                                                                                className="row col-12 justify-content-center align-items-center">
                                                                                <Card
                                                                                    value={itemFromApi[itemFromTheForm[0]]}/>
                                                                            </Td>

                                                                        default:
                                                                            return <Td key={itemKeyFromApi}
                                                                                       className="col justify-content-center fs-6">{itemFromApi[itemFromTheForm[0]] ? itemFromApi[itemFromTheForm[0]] :
                                                                                <div
                                                                                    className="btn btn-dark text-white border-0"></div>}</Td>
                                                                    }
                                                                }


                                                            }
                                                        })}</Tr>)
                                                }
                                            )}

                                    </Tbody>
                                </Table>
                                <div className="row col-12 justify-content-center mt-5 mb-5"><Pagination
                                    modules={this.props.modules}/></div>
                            </div>}


                    </div>
                ) : <Error404/>
            )
            }
        </div>)
}
}


export default connect(
    state => ({
        table: state.UMODULE,
        token: state.SESSION.session.token
    }),
    dispatch => ({
        readTableInformation: (payload)=> dispatch(uModuleRequest(payload))
    })
)(withRouter(TableList))

