import React, {Component} from 'react';
import {connect} from "react-redux";
import {saveDraftRequest} from "../../../store/actions/common";
import {withRouter} from "react-router-dom";



class Percentage extends Component {
    constructor(props) {
        super(props);
        this.state = {
            value: this.props.value ? this.props.value : ''
        }
    }
    handle(e){
        const { name, onChangeValue } = this.props;
        this.setState(() => {
            onChangeValue({
                [name]: e.target.value
            })
            return {
                value: e.target.value
            }
        })


    }

    render() {
        const { name, type } = this.props;
        const value = this.state.value;
        return (
            <div className="row">
                <div className="row">
                    Valor de Porcentaje: {((1 - parseFloat(value)) * 100 * -1).toFixed(2)}
                </div>
                <input type={type} value={value} name={name} onChange={e => this.handle(e)}/>
            </div>
        );
    }
}


export default connect(
    (state) => ({
        table: state.UMODULE,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload,
        token: state.SESSION.session.token,
    }),
    (dispatch) => ({
        saveDraft: (payload) => dispatch(saveDraftRequest(payload))
    })
)(withRouter(Percentage));
