import React, {Component} from "react";
import {findIndex, map} from "lodash";
import {connect} from "react-redux";
import {saveDraftRequest} from "../../../store/actions/common";
import {withRouter} from "react-router-dom";
import { uModuleRequestCud} from "../../../store/actions/uModule";
import Loading from "../Loading";
import ValueHandler from "./ValueHandler";
import  {validateArrayList} from "../../../store/services/validationService";
import DeleteEntry from "./DeleteEntry";

class FormBuild extends Component {
    constructor(props) {
        super(props);
        this.state = {
            chapter: 0,
            enabledSending: true,
            values: this.props.mode === 'create' ? {} : this.props.values,
            invalid: {}
        }
    }

   async onClickHandler(e){
        e.preventDefault();
        const {sending, error} = this.props.cud;
        const {savedFromDraft, modules, validate} = this.props;
        if(!(sending)){
        this.setState(()=>{
            const invalid = validateArrayList(validate,savedFromDraft[modules] )
            let payload = {
                modules: this.props.modules,
                mode: this.props.mode
            }
            if(!(sending && error) && (invalid.length < 1)) {
               this.props.postToApi(payload)
            }

            return {invalid: invalid}
        })
    }}
    resetValidationState(){
        this.setState({invalid:{}})
    }
    onClickForChapter(key){
        this.setState({chapter: key})
    }
    render(){
        const {compList, savedFromDraft, modules, mode, token} = this.props;
        const {chapter, invalid} = this.state;
        let flags = []
        for(const i in compList){
            if(compList[i][0] === 'chapter'){
                flags.push(Number(i))
            }
        }
        let nextFlag = flags[findIndex(flags, (itm)=>{return itm === this.state.chapter})+1]

        if(this.props.mode === 'delete'){
            return savedFromDraft && savedFromDraft[modules] ?
                <div className="row col-12 justify-content-center align-items-center">
                    <DeleteEntry
                    values={savedFromDraft[modules]}
                    modules={modules}
                    compList={compList}
                    token={this.props.token}
                    />
                </div>  :  (< div className="row col p-0 m-0 justify-content-center align-content-center">Hubo un error</div>)
        }
        return (
                <div className="row justify-content-center p-0 m-0">
                    <div className="row justify-content-start">
                        {map(compList, (itm, key)=>{
                            if(itm[0] === 'chapter'){
                                return (
                                    <div className="row col justify-content-start" key={key}>
                                        <button onClick={()=>this.onClickForChapter(key)} className=" btn btn-danger col m-5">{itm[1]}</button>
                                    </div>
                                )}
                        })}
                    </div>
                    {
                        savedFromDraft && savedFromDraft[modules] ?
                            <div className="row col p-0 m-0 justify-content-center align-content-center">
                                <ValueHandler
                                    chapter={chapter}
                                    nextFlag={nextFlag}
                                    compList={compList}
                                    invalid={invalid}
                                    savedDraftDad={savedFromDraft[modules]}
                                    modules={modules}
                                    token={token}
                                    resetInvalid={()=>this.resetValidationState()}
                                />
                            </div>
                            :  (< div className="row col p-0 m-0 justify-content-center align-content-center">Hubo un error</div>)
                    }
                    <div className="row">
                        <div className="row mt-3 col mt-5 justify-content-center align-content-center">
                            <div className="row col-sm-4 justify-content-center align-content-center">
                                {
                                    this.props.cud.sending ? <Loading /> :
                                        <button
                                            disabled={!(invalid)}
                                            onClick={(e)=>this.onClickHandler(e)}
                                            className="col btn btn-danger">
                                            {mode === 'create' ? 'Enviar' : mode === 'update' ? 'Modificar': 'Eliminar'}
                                        </button>
                                }
                             </div>
                        </div>
                    </div>
                </div>
            )
        }



}
export default connect(
    state => ({
        session: state.SESSION.session,
        table: state.UMODULE,
        cud: state.UMODULECUD,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload

    }),
    dispatch => (
        {
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload)),
        postToApi: (payload)=> dispatch( uModuleRequestCud(payload))
    }
    ))(withRouter(FormBuild))
