import React, {Component} from 'react'
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";
import {saveDraftRequest, universalFetch} from "../../../store/actions/common";
import {map} from "lodash";
import Loading from "../Loading";
import {Error404} from "../index";
import Http from "../../../store/services/http"
import {areaCode} from "../../../store/services/areaCodes";

class CreateNewPerson extends Component {
    constructor(props) {
        super(props);
        this.state = {
            error: '',
            phone: '',
            car: '',
            name:'',
            age: new Date,
            email: ''
        }

    }
    handleChange(e){
        this.setState({
            [e.target.name]: e.target.value
        })
    }
    async handleCreate(){
        const {value} = this.props
        const { phone, car, name, age, email} = this.state;
        const body = {
                dni: value,
                phone: (car ) +'-'+ (phone),
                value: '0',
                name: name ,
                age: age ,
                email: email
            }
            const url = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY+'clients/create'
            const createNewUserResponse = await Http.post(url, body, this.props.token)
            if(!createNewUserResponse.isError){
                    await this.props.handleSearch()
            } else {
                this.setState({error: createNewUserResponse.message})
            }


    }
    render(){
        const {message, value } = this.props
        const {phone, car, name, age, email} = this.state
        return (
            <div className={'row col-sm-12 mb-3 justify-content-center'}>
                <div className={' row col-sm-12 col-lg-6 justify-content-center'}>
                    <div className={'col row'}>{message.message}</div>
                    <div className={'col'}>-{value}-</div>
                    <div className={'col'}> {car.length > 1 ? areaCode((car ? car : 11)) : ''}</div>
                </div>
                <div className={'col-12 row justify-content-center'}>
                    <div className={'row col-12 justify-content-center'}>


                        <div className={' row col-sm-10'}><input name={'car'} placeholder={'Area'} className={'input'}
                                                                 value={car === '0' ? '' : car} type={'string'}
                                                                 onChange={(e) => this.handleChange(e)}/>
                        </div>
                        <div className={' row col-sm-10'}><input name={'phone'} placeholder={'Numero'}
                                                                 className={'input'} value={phone === '0' ? '' : phone}
                                                                 type={'string'}
                                                                 onChange={(e) => this.handleChange(e)}/>
                        </div>
                        <div className={' row col-sm-10'}><input placeholder={'Nombre'} name={'name'}
                                                                 className={'input'} value={name === '0' ? '' : name}
                                                                 type={'string'}
                                                                 onChange={(e) => this.handleChange(e)}/>
                        </div>
                        <div className={' row col-sm-10'}><input
                                                                data-date=""
                                                                data-date-format="YYYY-MM-DD"
                                                                placeholder={'Edad'}
                                                                name={'age'}
                                                                className={'input'}
                                                                value={age === '0' ? '' : age}
                                                                type={'date'}
                                                                onChange={(e) => this.handleChange(e)}/>
                        </div>
                        <div className={' row col-sm-10'}><input placeholder={'Email'} name={'email'}
                                                                 className={'input'} value={email === '0' ? '' : email}
                                                                 type={'text'}
                                                                 onChange={(e) => this.handleChange(e)}/>
                        </div>
                    </div>
                    <div className={'row col-6 mb-3'}>
                        <button className={'btn btn-danger btn-sm'} onClick={() => this.handleCreate()}>Crear</button>
                    </div>
                </div>

            </div>
        )
    }
}

class ShowPersonFound extends Component {
    constructor(props) {
        super(props);
    }


    render() {
        const {extra, message} = this.props;
        return (
            <div className="row col justify-content-center align-content-center p-0 m-0">
                {map(extra[4], (index, label)=>{
                        return map(message.message, (item, key)=>{

                            if(index === key){
                                return (
                                    <div className="row col-sm-12 col-lg-8 d-inline-block justify-content-center align-content-center p-0 m-0" key={key}>
                                        <div className="row col ">
                                            <div className="row col justify-content-center m-2">{extra[6][label]}:</div>
                                            <div className="row col fw-bold p-0 m-0 m-sm-2 m-3 text-decoration-underline ">

                                                {(index === 'value' ?item+' -> $':'')}
                                                {(index === 'phone' ? item+'(--'+areaCode(((item.split('-')[0]) !== 0 ? (item.split('-')[0]) :11)): '')}
                                                {(index === 'age')? item.toString().split('T')[0] : ''}
                                                {(index === 'name') ? item : ''}
                                                {(index === 'dni') ? <div style={{color: 'red'}} >{item}</div> : ''}
                                                {(index === 'email') ? item : ''}
                                            </div>
                                        </div>

                                    </div>
                                )
                            }

                        })
                    }
                )}
            </div>
        )
    }

}

class ModalViewPerson extends Component {
    constructor(props) {
        super(props);
    this.state = {
        showing: true,
    }
    }
    handleCloseButton(){
        this.setState((prevState)=>{
            return {showing: !prevState.showing}
        })
    }

    render() {
        const {type, message, extra, values, token} = this.props;

        if(!this.state.showing){
            return <div/>
        }
        return ((<div className={'modal-view-person row col-12 justify-content-center align-content-center '}>
            <div className={'row bg-dark'}>
                <div className="row col-12 justify-content-end ">
                    <i className="row col-1 justify-content-center align-items-center bi bi-x " onClick={()=>this.handleCloseButton()}></i>
                </div>
            </div>
            <div className="row justify-content-center align-items-center bg-dark">
                {type ?
                    <CreateNewPerson handleSearch={this.props.handleSearch} token={token} message={message} value={values}/> :
                    <ShowPersonFound message={message} extra={extra}/>}
            </div>

        </div>))
    }
}

class PersonSearch extends Component {

    constructor(props) {
        super(props);
        const { savedFromDraft, modules, name} = this.props;
        this.state = {
            values: savedFromDraft[modules] ?  savedFromDraft[modules][name] : '',
            create: false
        }

    }
    handleChange(e){
        this.setState(
            () => {
                return {values: e.target.value}
            })
    }

    handleSearch(){
        const {modules, extra,  name} = this.props;
            this.props.universalFetch({
                url: extra[3],
                body: {dni: parseInt(this.state.values, 10)},
                name: name,
                modules: modules
            })
    }
    handleSave(){
        const {onChangeValue,name} = this.props;
        onChangeValue({[name]: this.state.values})
    }



    render(){
        const {values} = this.state;
        const { label, savedFromDraft, modules, extra, name, ufetch, token} = this.props;
        const composedUfetch = ufetch.payload  && ufetch.payload[modules] && ufetch.payload[modules][name]
return (
    <div className={"row  justify-content-center mt-2 p-0 m-0"}>
            <div className="row fs-3">
                {label}
            </div>

            <div className="row justify-content-center">
                <div className="row col-12 justify-content-between p-0 m-0">
                    <input className={" col-sm-12 col-lg-8 text-white"} type="number" name="searchInput"
                           value={values ? values : 'Vacio'}
                           onChange={(e) => this.handleChange(e)}/>
                    <div className=" mt-1 col-sm-12 col-lg-2 row justify-content-around " >
                        <button className="row col btn btn-danger " onClick={(e) => this.handleSearch(e)}>
                            <i className="bi bi-search fs-3 fw-bold"/>
                        </button>
                    </div>
                    <div className=" mt-1 col-sm-12 col-lg-2 row justify-content-around " >
                        <div className="row col btn  btn-danger" onClick={() => this.handleSave()}>
                            <i className="bi bi-save fs-3 fw-bold"/>
                        </div>
                    </div>
                </div>
            </div>

            <div className="row col-sm-12 col-lg-6 mt-5 mb-5 ">
                <div className="row col  align-content-center">
                    <div className="">
                        Cliente Guardado
                    </div>
                    </div>
                <div className="row col  justify-content-center align-content-center ">
                    <div className="row col justify-content-center fw-bold"
                        style={{color: 'yellow', backgroundColor: 'red', borderRadius: '5%', flex: '2 2 10%'}}>
                        {savedFromDraft[modules][name] ? savedFromDraft[modules][name] : 'Sin Cliente'}
                    </div>
                </div>
            </div>

        <div>
            {ufetch.error && ufetch.success ? <Error404 label={'Error'}/> :
                (ufetch.loading || this.state.loading ? <Loading label={'Cargando'} modal={true}/> :
                        (  composedUfetch ?
                            <ModalViewPerson
                                type={ufetch.payload[modules][name].isError}
                                token={token}
                                extra={extra}
                                message={ufetch.payload[modules][name]}
                                handleSearch={()=>this.handleSearch()}
                                values={values}
                                onChangeValue={(e)=>this.handleChange(e)}
                            />
                : <div/>
                        )
                    )
                }
            </div>


    </div>
)}



}


export default connect(
    (state) => ({
        ufetch: state.UFETCH,
        table: state.UMODULE,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload,
        token: state.SESSION.session.token,
    }),
    (dispatch) => ({
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload)),
        universalFetch:(payload)=> dispatch(universalFetch(payload))
    })
)(withRouter(PersonSearch));
