import React, {Component} from 'react';

import {filter, map} from "lodash";
import {getFromApi} from "../../../store/services/getFromApiSimple";
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";


class SelectSimple extends Component {
    constructor(props) {
        super(props);
        this.state = {
            options: [],
            values: [],
            selectInput: 'default'
        }

    }
    async componentDidMount() {
        if(this.props.value){
            const source = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + this.props.extra[3];
            const response = await getFromApi(source, {_id: this.props.value}, this.props.token).then((itm) => {return (itm.message)}, () => {return {label: "No encontrado", value: 'default'}})
            await this.setState( () => {
                return {values: response.message}
            })
        }
    }

    async handleSearch(e){
        const source = process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + this.props.extra[3]
        const searchVector = this.props.extra[8] || 'label'
        if(e.target.name === 'searchInput' && e.target.value.length > 2){
            const response =await  getFromApi(source, {[searchVector]: e.target.value}, this.props.token).then(
                (itm)=>{return (itm.message)},
                ()=>{return {label: "No encontrado", value: 'default'}})
            this.setState({options: response.message})
        }}


    handleSelect(e){
        this.setState({[e.target.name]: e.target.value})
    }

    handleChange(){
        const {  extra, onChangeValue} = this.props;
            this.setState(
                prevState => {
                    const state = prevState
                    if(state.selectInput !== 'default'){
                        const vector = [...state.values, state.options[state.selectInput]].filter((itm)=>{return itm._id})
                        const toGlobalState = [...map(vector, (itm)=>{return itm._id})]
                        onChangeValue({
                            [extra[1]]: toGlobalState})
                        return {values:  vector}
                    }
                }) //save values
            //save them to global state
    }

    handleDelete(e){
        this.setState(prevState =>{
            const {  name} = this.props;
                const newValues = filter(prevState.values, (itm, ind)=>{
                    return ind!== e
                })
                const toGlobalState = [...map(newValues, (itm)=>{return itm._id})]
                this.props.onChangeValue({
                    [name]: toGlobalState
                })
                return {
                    values: newValues
                }
            }

        )

    }
    render() {
        return (
            <div>
                <div className={"row justify-content-center mt-2 "}>
                    <div className="row fs-3">
                        {this.props.label}
                    </div>
                    <div className="row justify-content-between">
                        <input className={" col-sm-4  bg-black text-white"} type="text" name="searchInput" onChange={(e)=>this.handleSearch(e)}/>
                        <select  className={"col-sm-4  bg-black text-white"} name="selectInput" onChange={(e)=>this.handleSelect(e)}>
                            <option value={'default'} >Seleccione</option>
                            {map(this.state.options, (opt, ind)=>{
                                return <option value={ind} key={ind}> {map(this.props.extra[4], (itm)=>{return ('  ' +opt[itm])})}</option>
                            })}
                        </select>
                        <button onClick={()=>this.handleChange()} className={"btn btn-dark text-white col-sm-3 border-danger m-1 p-1"}> Agregar</button>

                    </div>
                    <div className="row">
                        {this.state.values.length > 0 ?
                            <div className="bg-dark border-danger">
                                {map(this.state.values, (value, index)=>{

                                    return (
                                        <div key={index} className="row">
                                            <div className="col-10 ">
                                                {map(this.props.extra[4], (itm)=>{return (

                                                    '  ' +value[itm])})}
                                            </div>
                                            <div className="col-2 justify-content-end">
                                                <button onClick={()=>this.handleDelete(index)} className="btn btn-danger fw-bold">X</button>
                                            </div>

                                        </div>


                                    )
                                })}

                            </div> : <div/>

                        }
                    </div>

                </div>
            </div>
        );
    }
}

export default connect()(withRouter(SelectSimple));
