const getFromApi = async (url, body, token) => {
    try {

        const response = await fetch(url, {
            method: 'post',
            body: JSON.stringify(body),
            headers: {
                'content-type': 'application/json',
                'token': token,
                'simple': false
            }
        });

        return {isError: false, message: response.json()}
    } catch (parseError) {
        return {isError: true, message: {label: "No se encontro nada", value: undefined}};
    }


}
export {getFromApi}
