const getAtFlightValues = (range) =>{
    let total = 0; // Total
    let totalPorTarjeta = {} // obj with all cards totals
    // --- Promo dictionaries
    let promotionsDictionary = {}

    for (const sell in range){
        const actualSell = range[sell] // La venta en si
        const isConfirmedAndAccepted = actualSell.accepted && actualSell.confirmed
        if (isConfirmedAndAccepted){
            total = total +  parseInt(actualSell.total, 10)
            for(const promo in actualSell.promotion){
                const promoId = actualSell.promotion[promo]._id // guardo el ID
                if (promotionsDictionary[promoId] && promotionsDictionary[promoId].cell === promoId){

                    promotionsDictionary[promoId].value = promotionsDictionary[promoId].value +  parseInt(actualSell.promotion[promo].total, 10)
                    promotionsDictionary[promoId].cell = promotionsDictionary[promoId].cell + ' ' +actualSell._id
                }
                else {
                    promotionsDictionary[promoId] =
                        {
                            value: parseInt( actualSell.promotion[promo].total , 10 ),
                            label: actualSell.promotion[promo].label ,// "label": "Tarjeta Debito"
                            type: actualSell.promotion[promo].type,
                            cell: actualSell._id
                        }

                }


            }

        }

    }
    totalPorTarjeta = promotionsDictionary
    return {
        total,
        totalPorTarjeta,
    }


}
function parseObjectToCSV(data) {
    let dataNew
    let csv = ""
    const replaceCommas = obj => {
        if (typeof obj === 'object') {
            for (let key in obj) {
                if (typeof obj[key] === 'string') {
                    obj[key] = obj[key].replace(/,/g, '.');
                } else if (typeof obj[key] === 'object') {
                    obj[key] = replaceCommas(obj[key]);
                }
            }
        }
        return obj;
    };
    dataNew = replaceCommas(data)
    dataNew.forEach((obj) => {
        const {type, client, ticketNum, opNum, cashier, total, creator, updatedAt,products, promotion } = obj
        let productsEcuation = '';
        let productsName = '';
        products.forEach((product) => {
            productsEcuation += `${product.apValue} * ${product.value} * ${product.amount} +`;
            productsName += ` ## ${product.productName} - ${product.apName } ## `
        });
        productsEcuation.slice(productsEcuation.length,productsEcuation.length)
        let promotionsEcuation = '';
        let promotionsDescription = '';
        let promotionsName = '';
        promotion.forEach((promotionList)=>{
            promotionsEcuation += `${promotionList.value} *`;
            promotionsDescription += `${promotionList.value} - `;
            promotionsName += `${promotionList.label} - `
        });


        csv += `${type},${updatedAt.split('T')[0]},${promotionsDescription},${promotionsEcuation.slice(0, promotionsEcuation.length-1)}, ${promotionsName},${productsEcuation.slice(0, productsEcuation.length-1)},${productsName},${total},${cashier.split('@')[0]},${creator.split('@')[0]},${ticketNum},${opNum},${client}\n`;

    });
    return csv;
}


const flattenObject = (data, prods)=>{
    const headers = 'Tipo, Fecha, Promocion, Valor Promocion, Nombre de Promocion, Productos, Productos Nombres, Total, Cajero, Vendedor, Numero de Ticket, Numero de Operacion, Cliente\n';
    const body = parseObjectToCSV(data, prods)
   return headers+body+headers
}


