

function urlBase64ToUint8Array(base64String) {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);
    for (let i = 0; i < rawData.length; ++i) {
        outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
}

export default async function subscribeUserToPush(token) {
    const swRegistration = await navigator.serviceWorker.ready;
//TODO: FETCH VAPID PUBLIC KEY

    const fetchVapidPublicKey = await fetch(process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + 'api/vapidPublicKey/').then(response => response.json())
    if(fetchVapidPublicKey.isError){
        console.log('Error fetching Vapid Public Key')
    } else {
        const vapidPublicKey = fetchVapidPublicKey.message
        const applicationServerKey = urlBase64ToUint8Array(vapidPublicKey);
        const options = {
            userVisibleOnly: true,
            applicationServerKey: applicationServerKey
        };

        const subscription = await swRegistration.pushManager.subscribe(options);
        // Send the subscription object to your server
        // Replace this URL with your server's endpoint
        await fetch(process.env.REACT_APP_ENDPOINT_BACKEND_MAIN_CLOWNY + 'subscription/subscribe/', {
            method: 'POST',
            body: JSON.stringify(subscription),
            headers: {
                'Content-Type': 'application/json',
                token:token
            }
        });
    }


}





