import React, {Component} from "react";
import successIMG from "../../../images/success.svg";
import {Error404} from "../index";
import {connect} from "react-redux";
import {saveDraftRequest} from "../../../store/actions/common";
import {resetModuleCud} from "../../../store/actions/uModule";
import {withRouter} from "react-router-dom";
import FormBuild from "./FormBuild";
import Loading from "../Loading";

class AddNew extends Component {
    constructor(props) {
        super(props);
        this.state = {
            status: 'operative'
        }
    }

    onClick() {
        if (this.props.mode === 'create') {
            let payload = {
                modules: this.props.modules,
                mode: this.props.mode
            }
            this.props.postToApi(payload)
        } else {
            let payload = {
                modules: this.props.modules,
                mode: this.props.mode
            }
            if (!this.props.cud.sending) {
                this.props.postToApi(payload)
            }

        }

    }

    restartSucces(e) {
        e.preventDefault();
        this.props.handlePageModules('0', 'read', {}, '0')
    }

    render() {
        const {success, error, sending, payload} = this.props.cud;
        let errorMessage = 'Hubo un error, No estoy muy seguro cual'
        if(payload){
                    errorMessage =  payload[this.props.modules] ? payload[this.props.modules].message : ''
        }
        if (success) {
            return (<div className=" row justify-content-center align-content-center">
                <div className=" row col-12 justify-content-center align-content-center">
                    <img src={successIMG} alt="Success Marylin" style={{height: '30rem', width: '30rem'}}/>
                </div>
                <div className=" row col-3 col justify-content-center align-content-center">
                    Exitos! {errorMessage ? errorMessage : ''}
                </div>
                <div className=" row col justify-content-center align-content-center">
                    <i className="bi bi-gem text-white row col justify-content-center align-content-center "
                       style={{height: '8rem'}}></i>
                </div>
                <div className=" row col-sm-3 col justify-content-center align-content-center">
                    <button className={"btn btn-danger fs-1 text-white"} onClick={(e) => {
                        this.restartSucces(e)
                    }}>Volver
                    </button>
                </div>
            </div>)
        }
        if (error) {
            return (
                <Error404 label={errorMessage} handler={(e) => {
                    this.restartSucces(e)
                }}/>
            )

        }
        if (sending) {
            return (<Loading label={'Cargando'} size={'bg'}/>)
        } else {
            return (
                <div className={" row justify-content-center align-content-start fs-3 pt-5 m-0 text-white"}>
                    <FormBuild
                        compList={this.props.form}
                        mode={this.props.mode}
                        token={this.props.session.token}
                        validate={this.props.validate}
                        modules={this.props.modules}
                        values={this.props.valuesUpdate}
                    />
                </div>
            )
        }
    }
}
export default connect(
    state => ({
        session: state.SESSION.session,
        table: state.UMODULE,
        cud: state.UMODULECUD

    }),
    dispatch => ({
        saveDraft: (payload)=> dispatch(saveDraftRequest(payload)),
        resetApi: ()=>dispatch(resetModuleCud())
    }))(withRouter(AddNew))
