import React, {Component} from 'react';
import {connect} from "react-redux";
import {withRouter} from "react-router-dom";
import ComponentCustom from "../Components";
import {saveDraftRequest} from "../../../store/actions/common";
import {uModuleRequestCud} from "../../../store/actions/uModule";
import {isEqual, map} from "lodash";
import ValidationComponent from "./Validation";



class ValueHandler extends Component {
    constructor(props) {
        super(props);
        const {modules, savedFromDraft} = this.props;
        this.state= {
            values: savedFromDraft[modules]
        }
    }



    onChangeValue( value) {
        const {modules, savedFromDraft, saveDraft, draft} = this.props;
        const newDictionary = {
            ...savedFromDraft[modules],
            ...value,
        }
        if(!isEqual(newDictionary,savedFromDraft[modules])){
            this.setState(()=>{
                            // Create a new copy of the dictionary with the updated value
                            this.props.resetInvalid()
                            const newDictionary = {
                                ...savedFromDraft[modules],
                                ...value,
                            }
                            const payload = {
                                values: newDictionary,
                                modules: modules
                            }
                            if(!draft.loading){
                                saveDraft(payload)
                            }

                            return {values:newDictionary}


                        })
        }
    }


    render() {
        const {chapter, nextFlag, compList, invalid, savedDraftDad, modules, token} = this.props;
        const hasInvalid = invalid.length > 0
        let invalidMessage = {}
        if(hasInvalid){
            for(const item in compList){
                const message = map(invalid, (invalidItem)=>{
                    if(invalidItem.name === compList[item][1] && invalidItem.value){
                        return invalidItem.message
                    }
                })
                invalidMessage[compList[item][1]] = message.filter((item)=>{return item !== undefined})
            }
        }
        return (
            <div className={'row'}>
                {map(compList, (itm, i)=>{
                    if ( i > chapter && (nextFlag ? i < nextFlag : true)){
                        return (
                            <div className="row col-12 p-0 m-0 pt-3 mt-5 " key={i}>
                                <div className="col-sm-12 col-lg-4">
                                    {itm[2]}
                                </div>
                                <div className="col-sm-12 col-lg-8 fs-6 text-danger">
                                    <ValidationComponent
                                        message={invalidMessage[itm[1]] ? invalidMessage[itm[1]] : ''}
                                    />
                                </div>
                                <div className="row col p-0 m-0 ">
                                    <ComponentCustom
                                        invalid={invalid}
                                        savedDraftDad={savedDraftDad}
                                        extra={itm}
                                        modules={modules}
                                        type={itm[0]}
                                        name={itm[1]}
                                        token={token}
                                        onChangeValue={(name, value)=>this.onChangeValue(name, value)}
                                        values={this.state.values}
                                    />
                                </div>
                            </div>)
                    }
                })
                }
            </div>
        );
    }
}

export default connect(
    state => ({
        session: state.SESSION.session,
        table: state.UMODULE,
        cud: state.UMODULECUD,
        draft: state.SAVE_DRAFT,
        savedFromDraft: state.SAVE_DRAFT.payload

    }),
    dispatch => (
        {
            saveDraft: (payload)=> dispatch(saveDraftRequest(payload)),
            postToApi: (payload)=> dispatch( uModuleRequestCud(payload))
        }
    ))(withRouter(ValueHandler));


