import React, {Component} from 'react';
import {map} from "lodash";
import {connect} from "react-redux";
import {uModuleRequest} from "../../../store/actions/uModule";
import {withRouter} from "react-router-dom";


class HeaderSearch extends Component {
    constructor(props) {
        super(props);
        this.state = {
            body: {},
            fold: false
        }
    }



    handleSearch(){
        this.props.readTableInformationCallback(this.state.body)
    }
    handleClear(){
        this.setState({body: {}})
    }
    handleSearchInput(e){
        this.setState(prevState => {
            const body = {...prevState.body,[e.target.name]:e.target.value}
            return {body: body}})
    }
    handleSearchInputCheckBox(e){
        this.setState(prevState => {
            const body = {...prevState.body, [e.target.name]: e.target.checked}
            return {body:body}})
    }
    handleSelect(e, trip){
        this.setState(prevState => {
            const body = {...prevState.body, [trip[0]]: trip[3][e.target.value]}
            return {body:body}})
    }
    handleNumber(name,number){
        this.setState(prevState => {
            const body = {...prevState.body, [name]: number}
            return {body:body}})
    }
    render() {
        const query = (trip) =>{
            switch (trip[0]){
                case 'UPDATE': return false;
                case 'DELETE': return false;
                case 'date': return false;
                case 'index': return false;
                default:{
                    switch (trip[2]){
                        case 'checkbox': {return <input checked={this.state.body[trip[0]]} name={trip[0]} className={"col-sm-6  input-text"} type={trip[2]} onChange={(e)=>this.handleSearchInputCheckBox(e)}></input>}
                        case 'number': {return <input
                            value={this.state.body[trip[0]] || this.props.prevState[trip[0]]}
                            name={trip[0]} className={"col-sm-6 input-text"} type={trip[2]}
                            onChange={(e)=>this. handleNumber(e.target.name,parseInt(e.target.value))}
                        />

                            }
                        case 'select': { return <select className={"col-lg-6"} name={trip[0]} defaultValue={trip[3][0]} onClick={(e)=>this. handleSelect(e, trip)}>
                                                    {map(trip[3], (item, index)=>{
                                                        return <option value={index} label={item.name} key={index}>{trip[3][index]}</option>
                                                    })}
                                                </select>}
                        default: return <input  value={this.state.body[trip[0]] || this.props.prevState[trip[0]]} name={trip[0]} className={"col-sm-6  input-text"} type={trip[2]} onChange={(e)=>this.handleSearchInput(e)}></input>
                    }
                }
            }
        }
        return (
            <div className={"row swing-in-top-fwd justify-content-start p-0 m-0 pb-0 " }>
                        <div>
                                <div className="row col align-content-between ">
                                        {map(this.props.header, (triplet, key)=>{
                                            if(!query(triplet)){return <div/>}
                                            return (
                                                <div className="row align-items-center text-danger p-0 mt-3 ">
                                                    <div key={key} className="row align-items-center text-danger p-0 mt-3 ">
                                                        <div className="col-6 row justify-content-center text-truncate">
                                                            {triplet[1]}
                                                        </div>
                                                        <div className="row col-6 justify-content-center fs-5">
                                                            {query(triplet, key)}
                                                        </div>
                                                    </div>
                                                </div>
                                            )

                                        })}
                                </div>
                            <div className="row justify-content-center align-items-center  p-0  mt-4">
                                <div className="row align-items-center justify-content-evenly col mb-3 ">
                                        <button className="btn btn-danger fw-bold fs-6 col-4" onClick={(e) => this.handleSearch(e)}>Buscar</button>
                                        <button className="btn btn-danger fw-bold fs-6 col-4" onClick={(e) => this.handleClear(e)}>Limpiar</button>
                                    </div>
                                </div>
                        </div>
            </div>
        );
    }
}

export default connect(
    state => ({
        table: state.UMODULE,
    }),
    dispatch => ({
        readTableInformation:( payload)=> dispatch(uModuleRequest(payload))
    })
)(withRouter(HeaderSearch))
